pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;
    function setUp() public { c = new VaultAdapter(); }

    function testFuzz_property(address admin) public {
        // The implementation contract disables its initializers in the constructor,
        // so exercise initialize() through a minimal delegatecall proxy (fresh storage).
        MinimalProxy p = new MinimalProxy(address(c));

        bool firstOk;
        (bool s1, ) = address(p).call(abi.encodeWithSignature("initialize(address)", admin));
        firstOk = s1;

        bool secondOk;
        (bool s2, ) = address(p).call(abi.encodeWithSignature("initialize(address)", admin));
        secondOk = s2;

        // General rule: initialize succeeds at most once; a second initialize must revert.
        assertTrue(!firstOk || !secondOk);
    }
}

contract MinimalProxy {
    address public immutable impl;
    constructor(address i) { impl = i; }
    fallback() external payable {
        address _impl = impl;
        assembly {
            calldatacopy(0, 0, calldatasize())
            let ok := delegatecall(gas(), _impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch ok
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }
}
